package com.example.order.config;

import java.time.Duration;
import org.springframework.boot.context.properties.ConfigurationProperties;
import org.springframework.boot.context.properties.bind.DefaultValue;

/** order.* 설정 (01 문서 10절). ORDER_PAYMENT_TTL 은 application.yml 의 placeholder 로 매핑된다. */
@ConfigurationProperties(prefix = "order")
public record OrderProperties(
        @DefaultValue("PT15M") Duration paymentTtl,
        @DefaultValue Expiry expiry,
        @DefaultValue Idempotency idempotency) {

    public OrderProperties {
        requirePositive(paymentTtl, "order.payment-ttl");
    }

    public record Expiry(
            @DefaultValue("PT0.2S") Duration sweepInterval,
            @DefaultValue("PT10S") Duration inFlightTimeout) {
        public Expiry {
            requirePositive(sweepInterval, "order.expiry.sweep-interval");
            requirePositive(inFlightTimeout, "order.expiry.in-flight-timeout");
        }
    }

    public record Idempotency(@DefaultValue("PT30S") Duration inProgressTimeout) {
        public Idempotency {
            requirePositive(inProgressTimeout, "order.idempotency.in-progress-timeout");
        }
    }

    private static void requirePositive(Duration d, String name) {
        if (d == null || d.isZero() || d.isNegative()) {
            throw new IllegalArgumentException(name + " must be a positive ISO-8601 duration");
        }
    }
}

package com.example.order.config;

import java.time.Duration;
import org.springframework.boot.context.properties.ConfigurationProperties;
import org.springframework.boot.context.properties.bind.DefaultValue;

/** payment.gateway.* 설정. PAYMENT_GATEWAY_URL 은 application.yml 의 placeholder 로 매핑된다. */
@ConfigurationProperties(prefix = "payment.gateway")
public record PaymentGatewayProperties(
        @DefaultValue("http://localhost:9090") String url,
        @DefaultValue("PT2S") Duration timeout) {

    public PaymentGatewayProperties {
        if (timeout == null || timeout.isZero() || timeout.isNegative()) {
            throw new IllegalArgumentException("payment.gateway.timeout must be positive");
        }
    }
}

package com.example.order.config;

import com.fasterxml.jackson.core.JsonParser;
import com.fasterxml.jackson.core.JsonToken;
import com.fasterxml.jackson.databind.DeserializationContext;
import com.fasterxml.jackson.databind.Module;
import com.fasterxml.jackson.databind.deser.std.StdScalarDeserializer;
import com.fasterxml.jackson.databind.module.SimpleModule;
import java.io.IOException;
import java.time.Clock;
import org.springframework.boot.context.properties.EnableConfigurationProperties;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.scheduling.annotation.EnableScheduling;

@Configuration
@EnableScheduling
@EnableConfigurationProperties({OrderProperties.class, PaymentGatewayProperties.class})
public class AppConfig {

    @Bean
    public Clock clock() {
        return Clock.systemUTC();
    }

    /**
     * String 대상 역직렬화는 JSON 문자열 토큰만 허용한다 (name: 123, cardToken: 1 -> 400).
     * Jackson 기본 StringDeserializer 는 숫자/불리언을 문자열로 강제 변환한다.
     */
    @Bean
    public Module strictStringModule() {
        SimpleModule module = new SimpleModule("strict-string");
        module.addDeserializer(String.class, new StrictStringDeserializer());
        return module;
    }

    static final class StrictStringDeserializer extends StdScalarDeserializer<String> {
        StrictStringDeserializer() {
            super(String.class);
        }

        @Override
        public String deserialize(JsonParser p, DeserializationContext ctxt) throws IOException {
            if (p.hasToken(JsonToken.VALUE_STRING)) {
                return p.getText();
            }
            return (String) ctxt.handleUnexpectedToken(String.class, p);
        }
    }
}

package com.example.order.config;

import java.time.Clock;
import java.time.Instant;
import java.time.temporal.ChronoUnit;
import org.springframework.stereotype.Component;

/** 앱이 만드는 모든 Instant 는 마이크로초로 절삭한다 (PostgreSQL TIMESTAMPTZ 정밀도, 01 문서 0.2절). */
@Component
public class AppClock {

    private final Clock clock;

    public AppClock(Clock clock) {
        this.clock = clock;
    }

    public Instant now() {
        return clock.instant().truncatedTo(ChronoUnit.MICROS);
    }
}

